<template>
  <el-popover v-model:visible="visible" placement="top-start" width="min(650px, calc(100vw - 32px))" trigger="click" :disabled="disabled">
    <template #reference><el-button class="modelTrigger" text :disabled="disabled" aria-label="选择生成模型">{{ selected?.label || automaticLabel || 'Pippit · 自动模型' }}⌄</el-button></template>
    <section class="mediaModelPicker"><nav><button v-for="tab in [{ id: 'video', name: '视频' }, { id: 'image', name: '图片' }]" :key="tab.id" type="button" :class="{ active: tab.id === activeKind }" @click="activeKind = tab.id">{{ tab.name }}</button></nav>
      <div class="modelColumns"><div class="modelChoices"><small>模型</small><button type="button" :class="{ selected: modelValue === 'pippit' }" @click="choose({ id: 'pippit', label: 'Pippit 智能选择', kind: activeKind })"><strong>Pippit 智能选择 <span v-if="modelValue === 'pippit'">✓</span></strong><small>使用 Pippit 账号，由服务自动选择模型与技能</small></button><button v-for="item in items.filter(item => item.kind === activeKind)" :key="item.id" type="button" :class="{ selected: modelValue === item.id }" @click="choose(item)"><strong>{{ item.label }} <span v-if="modelValue === item.id">✓</span></strong><small>{{ item.provider }} · 独立 API</small></button><p v-if="!items.some(item => item.kind === activeKind)">暂无已配置的独立 API 模型，可先在设置中添加。</p></div>
      <div class="modelParameters"><small>纵横比</small><div class="ratioOptions"><button v-for="value in selected?.ratios || ['9:16','3:4','1:1','4:3','16:9','21:9']" :key="value" type="button" :class="{ selected: ratio === value }" @click="emit('update:ratio', value)"><i :style="{ aspectRatio: value.replace(':','/') }" />{{ value }}</button></div><small>分辨率</small><div class="parameterOptions"><span v-if="modelValue === 'pippit'">由 Pippit 自动决定</span><button v-for="value in selected?.resolutions || []" :key="value" type="button" :class="{ selected: resolution === value }" @click="emit('update:resolution', value)">{{ value.toLowerCase() }}</button></div><template v-if="selected?.kind === 'video' && modelValue !== 'pippit'"><small>时长</small><el-select :modelValue="duration" aria-label="视频时长" @change="emit('update:duration', $event)"><el-option v-for="value in 9" :key="value" :value="value + 3" :label="`${value+3} 秒`" /></el-select></template></div></div><p v-if="error" role="alert">{{ error }}</p><footer>独立 API 使用该供应商的额度；Pippit 官网内部模型目录未通过当前接口开放。</footer>
    </section>
  </el-popover>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
const props = defineProps<{ modelValue: string; ratio: string; resolution: string; duration: number; automaticLabel?: string; disabled?: boolean }>();
const emit = defineEmits<{ 'update:modelValue': [value: string]; 'update:ratio': [value: string]; 'update:resolution': [value: string]; 'update:duration': [value: number]; selectKind: [value: string] }>();
type Model = { id: string; label: string; kind: string; provider?: string; ratios?: string[]; resolutions?: string[] };
const items = ref<Model[]>([]);
const visible = ref(false);
const activeKind = ref('video');
const error = ref('');
const selected = computed(() => items.value.find(item => item.id === props.modelValue));
function choose(item: Model) { emit('update:modelValue', item.id); emit('selectKind', item.kind); if (item.ratios?.length && !item.ratios.includes(props.ratio)) emit('update:ratio', item.ratios[0]!); if (item.resolutions?.length && !item.resolutions.includes(props.resolution)) emit('update:resolution', item.resolutions[0]!); }
onMounted(async () => { try { const response = await fetch(new URL('api/creation/models', `${window.location.origin}/`)); if (!response.ok) throw new Error('模型列表读取失败'); items.value = (await response.json()).items; } catch (cause) { error.value = cause instanceof Error ? cause.message : '模型列表不可用'; } });
</script>

<style scoped lang="scss">
.modelTrigger { max-width: 270px; min-width: 100px; padding: 0 14px; border-radius: 18px; background: var(--el-fill-color-light); font-size: 12px; font-weight: 400; :deep(span) { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; } }
.mediaModelPicker { nav { display: flex; gap: 4px; width: fit-content; padding: 3px; border-radius: 30px; background: var(--el-fill-color); button { padding: 7px 26px; border: 0; border-radius: 20px; background: none; color: inherit; cursor: pointer; &.active { background: var(--el-bg-color); } } } .modelColumns { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 20px; .modelChoices { max-height: 340px; overflow: auto; border-right: 1px solid var(--el-border-color-lighter); padding-right: 18px; > button { display: block; width: 100%; text-align: left; padding: 14px 10px; border: 0; border-radius: 12px; background: none; color: inherit; cursor: pointer; &.selected { background: var(--el-fill-color-light); } strong { display: flex; justify-content: space-between; font-size: 12px; font-weight: 500; } small { display: block; margin-top: 7px; line-height: 1.6; } } p { font-size: 12px; line-height: 1.7; color: var(--el-text-color-secondary); } } small { color: var(--el-text-color-secondary); font-size: 11px; } .modelParameters { display: flex; flex-direction: column; gap: 12px; } } .ratioOptions, .parameterOptions { display: flex; flex-wrap: wrap; gap: 4px; border-radius: 16px; padding: 5px; background: var(--el-fill-color-light); button { display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 9px; border: 0; border-radius: 12px; color: inherit; background: none; cursor: pointer; font-size: 11px; &.selected { background: var(--el-bg-color); } i { display: block; width: 13px; border: 1px solid currentColor; border-radius: 2px; } } span { font-size: 12px; padding: 8px; color: var(--el-text-color-secondary); } } footer { margin-top: 20px; padding-top: 12px; border-top: 1px solid var(--el-border-color-lighter); color: var(--el-text-color-secondary); font-size: 11px; } @media(max-width: 550px) { .modelColumns { grid-template-columns: 1fr; .modelChoices { border-right: 0; padding-right: 0; } } } }
</style>
